# Maryland Code from mgaleg.maryland.gov: every article's section list (api/Laws/GetSections), then each section's StatuteText box.
import re
BASE = "https://mgaleg.maryland.gov/mgawebsite"

def sections():
    _, page = fetch(BASE + "/Laws/Statutes")
    arts = []
    for code, name in re.findall(r'<option value="(g[a-z]{2})">([^<]+?) - \(g[a-z]{2}\)</option>', page):
        if code not in [a for a, _ in arts]:
            arts.append((code, name.strip()))
    log(f"{len(arts)} articles")
    for code, name in arts:
        try:
            secs = [s["DisplayText"] for s in fetch_json(f"{BASE}/api/Laws/GetSections?articleCode={code}&enactments=true")]
        except Exception as e:
            log(f"section list failed {code}: {e}"); continue
        log(f"{code} {name}: {len(secs)} sections")
        for sid in secs:
            url = f"{BASE}/Laws/StatuteText?article={code}&section={sid}&enactments=true"
            try:
                _, html = fetch(url)
            except Exception as e:
                log(f"failed {code} {sid}: {e}"); continue
            lines = block_text(html, id="StatuteText").split("\n")
            # the box: "Article - X", Previous/Next buttons, "§1–302.", the law, Previous/Next
            start = next((i for i, l in enumerate(lines) if l.startswith("§")), None)
            if start is None:
                log(f"no section mark {code} {sid}"); continue
            body = [re.sub(r"^§\s*\S+\s*", "", lines[start])] + lines[start + 1:]
            while body and body[-1].replace("Previous", "").replace("Next", "").strip() == "":
                body.pop()
            text = "\n".join(body).strip()
            if not text:
                continue
            yield {"id": sid, "heading": "", "text": text, "url": url, "vars": {"article": name}}
